CREATE TABLE IF NOT EXISTS pilot_report_profiles(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,rollout_id TEXT NOT NULL,timezone TEXT NOT NULL DEFAULT 'America/Chicago',integration_mode TEXT NOT NULL DEFAULT 'MANUAL_FALLBACK' CHECK(integration_mode='MANUAL_FALLBACK'),financial_autonomy INTEGER NOT NULL DEFAULT 0 CHECK(financial_autonomy=0),configured_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,rollout_id));
CREATE TABLE IF NOT EXISTS pilot_report_schedule_slots(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,profile_id TEXT NOT NULL,local_time TEXT NOT NULL,grace_minutes INTEGER NOT NULL DEFAULT 30 CHECK(grace_minutes BETWEEN 0 AND 240),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),created_at TEXT NOT NULL,UNIQUE(organization_id,profile_id,local_time));
CREATE TABLE IF NOT EXISTS pilot_report_types(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,profile_id TEXT NOT NULL,report_type TEXT NOT NULL CHECK(report_type IN('ARRIVALS','DEPARTURES','IN_HOUSE_GUESTS','ROOM_STATUS','HOUSEKEEPING','REVENUE','TRANSACTIONS')),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),created_at TEXT NOT NULL,UNIQUE(organization_id,profile_id,report_type));
CREATE TABLE IF NOT EXISTS pilot_property_contacts(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,contact_type TEXT NOT NULL CHECK(contact_type='SHARED_INBOX'),display_name TEXT NOT NULL,email TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'CONFIGURATION_REQUIRED' CHECK(status IN('CONFIGURATION_REQUIRED','VERIFIED','REVOKED')),created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,property_id,contact_type));
CREATE TABLE IF NOT EXISTS pilot_staff_assignments(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,user_email TEXT NOT NULL,display_name TEXT NOT NULL,phone TEXT,operational_role TEXT NOT NULL CHECK(operational_role IN('ENTERPRISE_OWNER','GENERAL_MANAGER','SUPERVISOR','HOUSEKEEPING')),enterprise_scope INTEGER NOT NULL DEFAULT 0 CHECK(enterprise_scope IN(0,1)),status TEXT NOT NULL DEFAULT 'INVITED' CHECK(status IN('INVITED','ACTIVE','SUSPENDED')),created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,property_id,user_email));
CREATE TABLE IF NOT EXISTS pilot_report_submissions(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,profile_id TEXT NOT NULL,report_type TEXT NOT NULL,scheduled_local_time TEXT NOT NULL,business_date TEXT NOT NULL,object_key TEXT NOT NULL,file_name TEXT NOT NULL,content_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,file_sha256 TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('RECEIVED','DUPLICATE','REJECTED','PROCESSING','PARSED','REVIEW_REQUIRED','FAILED','RECONCILED')),freshness_status TEXT NOT NULL CHECK(freshness_status IN('ON_TIME','LATE','UNSCHEDULED')),parse_error TEXT,uploaded_by TEXT NOT NULL,uploaded_at TEXT NOT NULL,reconciled_at TEXT,UNIQUE(organization_id,property_id,file_sha256));
CREATE TABLE IF NOT EXISTS pilot_report_events(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,submission_id TEXT,event_type TEXT NOT NULL,detail_json TEXT NOT NULL,actor_email TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS pilot_report_schedule_idx ON pilot_report_schedule_slots(organization_id,profile_id,active,local_time);
CREATE INDEX IF NOT EXISTS pilot_report_submission_scope_idx ON pilot_report_submissions(organization_id,property_id,business_date,report_type,status);
CREATE INDEX IF NOT EXISTS pilot_report_event_scope_idx ON pilot_report_events(organization_id,property_id,created_at);
